`,e.jsx(t.li,{children:"Replicate across groups"}),`
`,e.jsxs(t.li,{children:["ZeRO stages ↔ PyTorch FSDP ",e.jsx(s,{id:"zhao2023fsdp",children:"Zhao et al., 2023"})]}),`
`]}),e.jsxs(r,{title:"HSDP shards along one axis and replicates along another",children:[e.jsxs(t.p,{children:["The sharding group need not span the whole cluster. Hybrid sharded data parallel (HSDP) arranges the data-parallel ranks along two axes of process groups. Within each sharding group, the parameters, gradients and optimizer state are sharded as in full sharding. Across the groups, the matching shards are replicated, and the replica groups synchronize their gradients as in data parallelism ",e.jsx(s,{id:"zhao2023fsdp",children:"Zhao et al., 2023"}),". With a placement that follows the topology, the frequent all-gathers and reduce-scatters stay within a fast link domain, while the synchronization between replicas may cross slower links."]}),e.jsxs(t.p,{children:["The names come from two systems. DeepSpeed's ZeRO stages name the ladder of what is sharded. In PyTorch, DDP leaves the training state replicated, and FSDP2 shards it fully ",e.jsx(s,{id:"zhao2023fsdp",children:"Zhao et al., 2023"}),". With ",e.jsx(t.code,{children:"reshard_after_forward=False"}),", FSDP2 keeps the gathered parameters until backward, the ZeRO-2-style behavior of Llama 3's run."]})]})]})]}),`
`,e.jsxs(o,{tab:"Tensor Parallelism",plate:"ramelli-rack-pinions",children:[e.jsxs(a,{title:"Tensor parallelism splits each matrix across GPUs",reading:!0,accent:2,number:"28",children:[e.jsxs(t.ul,{children:[`
`,e.jsxs(t.li,{children:["ZeRO shards storage, TP shards compute ",e.jsx(s,{id:"shoeybi2019megatron",children:"Shoeybi et al., 2019"})]}),`
`,e.jsx(t.li,{children:"Up-projection: column split, GELU stays local"}),`
`,e.jsx(t.li,{children:"Down-projection: row split, partial sums"}),`
